package ai.satark.smsguard

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue

/** The chosen language. Screens read it through [tr], so they redraw when it changes. A native speaker should check the wording. */
object AppLang {
    val ALL = listOf("en" to "English", "hi" to "हिंदी", "bn" to "বাংলা", "mr" to "मराठी", "ta" to "தமிழ்", "te" to "తెలుగు")
    var code by mutableStateOf("en")
}

fun tr(key: String): String = WORDS[key]?.get(AppLang.ALL.indexOfFirst { it.first == AppLang.code }.coerceAtLeast(0)) ?: key

